function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // bird
  ctx.lineWidth = 3;
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 - 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + Math.cos(t) * 20, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 - 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - Math.cos(t) * 20, H/2);
  ctx.stroke();

  // fish
  ctx.beginPath();
  ctx.arc(W/2 - 100, H - 50 + Math.sin(t) * 20, 15, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H - 50 + Math.sin(t) * 20 + 15);
  ctx.lineTo(W/2 - 100, H - 50 + Math.sin(t) * 20 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H - 50 + Math.sin(t) * 20 - 15);
  ctx.lineTo(W/2 - 100 + Math.cos(t) * 10, H - 50 + Math.sin(t) * 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H - 50 + Math.sin(t) * 20 - 15);
  ctx.lineTo(W/2 - 100 - Math.cos(t) * 10, H - 50 + Math.sin(t) * 20);
  ctx.stroke();

  ctx.restore();
}
